function mergeSort(a) {
  if (a.length <= 1) return a;              // base case: stops the recursion

  const mid = Math.floor(a.length / 2);
  const left = mergeSort(a.slice(0, mid));  // runs to completion first
  const right = mergeSort(a.slice(mid));    // only starts once left returns

  return merge(left, right);
}

function merge(left, right) {
  const out = [];
  let i = 0, j = 0;

  while (i < left.length && j < right.length) {
    // <= not <: on a tie take the left, which is what keeps this stable.
    if (left[i] <= right[j]) out.push(left[i++]);
    else out.push(right[j++]);
  }

  // At most one of these runs. Whatever is left is already sorted and
  // already larger than everything emitted, so it is copied wholesale.
  while (i < left.length) out.push(left[i++]);
  while (j < right.length) out.push(right[j++]);
  return out;
}

