def merge_sort(a):
    if len(a) <= 1:
        return a                          # base case: stops the recursion

    mid = len(a) // 2
    left = merge_sort(a[:mid])            # runs to completion first
    right = merge_sort(a[mid:])           # only starts once left returns

    return merge(left, right)


def merge(left, right):
    out = []
    i = j = 0

    while i < len(left) and j < len(right):
        # <= not <: on a tie take the left, which keeps this stable.
        if left[i] <= right[j]:
            out.append(left[i]); i += 1
        else:
            out.append(right[j]); j += 1

    # At most one of these adds anything: the remainder is already sorted
    # and already larger than everything emitted so far.
    out.extend(left[i:])
    out.extend(right[j:])
    return out

#include <vector>

std::vector<int> merge(const std::vector<int>& left, const std::vector<int>& right) {
    std::vector<int> out;
    out.reserve(left.size() + right.size());
    size_t i = 0, j = 0;

    while (i < left.size() && j < right.size()) {
        // <= not <: on a tie take the left, which keeps this stable.
        if (left[i] <= right[j]) out.push_back(left[i++]);
        else out.push_back(right[j++]);
    }
    // At most one of these runs; the remainder is already sorted.
    while (i < left.size()) out.push_back(left[i++]);
    while (j < right.size()) out.push_back(right[j++]);
    return out;
}

std::vector<int> mergeSort(std::vector<int> a) {
    if (a.size() <= 1) return a;          // base case
    size_t mid = a.size() / 2;
    auto left  = mergeSort({a.begin(), a.begin() + mid});  // completes first
    auto right = mergeSort({a.begin() + mid, a.end()});
    return merge(left, right);
}
